INSERT INTO ${dynamicTableNameProxy.collaborateProduceBatchInfo}
    (contract_code, enterprise_code, produce_batch_number, enter_staff, primary_key)

SELECT #{contractCode},
       ${dynamicTableNameProxy.enterpriseCode},
       #{batchNum},
       ${dynamicTableNameProxy.currentCode},
       ${dynamicTableNameProxy.nextPrimaryKey} WHERE NOT EXISTS (
        SELECT 1 FROM ${dynamicTableNameProxy.collaborateProduceBatchInfo}
    WHERE contract_code = #{contractCode} for update
    );
